def main():
    n=int(input('What\'s n? '))
    for flock in copy2D(n+1):
        print(flock)

def copy2D(n:int):
    '''
    Return n number of input emojies.
    '''
    for i in range(n):
        yield '🦅'*i

if __name__=='__main__':
    main()